conformance.bend:
law count_correct:
  for +xs: List<&2, U32>
  {C.byte_count(xs, 0n) == List.length(&2, U32, xs) : Nat}

law length_correct:
  for +n: Nat
  {C.bit_length(n) == F.length_field(n) : List<&2, U32>}

law pad_correct:
  for +xs: List<&2, U32>
  {C.pad(xs) == F.pad(xs) : List<&2, U32>}

law words_correct:
  for bytes: List<&2, U32>
  {C.words(bytes) == F.words(bytes) : List<&2, U32>}

law next_correct:
  for +hs: List<&2, U32>
  {C.next_word(hs) == F.recurrence(hs) : U32}

law digest_correct:
  for s: S.State
  {C.digest(s) == F.digest(s) : List<&2, U32>}

list_proofs.bend:
law add_zero:
  for n: Nat
  {Nat.add(n, 0n) == n : Nat}

padding_proof.bend:
law zeros_correct:
  for r: Nat
  {Nat.mod(Nat.sub(119n, r), 64n) == F.zero_count(r) : Nat}
